class Solution {
public:
    ListNode* reverseEvenLengthGroups(ListNode* head) {
        vector<int> vals;
        for (ListNode* node = head; node; node = node->next) vals.push_back(node->val);
        int n = vals.size();
        vector<int> res;
        res.reserve(n);
        int i = 0, g = 1;
        while (i < n) {
            int len = min(g, n - i);
            if (len % 2 == 0)
                for (int k = i + len - 1; k >= i; k--) res.push_back(vals[k]);
            else
                for (int k = i; k < i + len; k++) res.push_back(vals[k]);
            i += len;
            g++;
        }
        ListNode dummy(0);
        ListNode* cur = &dummy;
        for (int v : res) {
            cur->next = new ListNode(v);
            cur = cur->next;
        }
        return dummy.next;
    }
};

