class Solution {
    public ListNode reverseEvenLengthGroups(ListNode head) {
        List<Integer> vals = new ArrayList<>();
        for (ListNode node = head; node != null; node = node.next) vals.add(node.val);
        int n = vals.size();
        int[] res = new int[n];
        int i = 0, g = 1;
        while (i < n) {
            int len = Math.min(g, n - i);
            for (int k = 0; k < len; k++) {
                int src = len % 2 == 0 ? i + len - 1 - k : i + k;
                res[i + k] = vals.get(src);
            }
            i += len;
            g++;
        }
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        for (int v : res) {
            cur.next = new ListNode(v);
            cur = cur.next;
        }
        return dummy.next;
    }
};

