    for (let node = head; node !== null; node = node.next) vals.push(node.val);
    const n = vals.length;
    const res = [];
    let i = 0, g = 1;
    while (i < n) {
        const len = Math.min(g, n - i);
        const chunk = vals.slice(i, i + len);
        if (len % 2 === 0) chunk.reverse();
        res.push(...chunk);
        i += len;
        g++;
    }
    const dummy = new ListNode(0);
    let cur = dummy;
    for (const v of res) {
        cur.next = new ListNode(v);
        cur = cur.next;
    }
    return dummy.next;
};

