class Solution:
    def reverseEvenLengthGroups(self, head: Optional[ListNode]) -> Optional[ListNode]:
        dummy = ListNode(0, head)
        group_prev = dummy
        size = 1
        while group_prev.next:
            tail = group_prev
            count = 0
            while tail.next and count < size:
                tail = tail.next
                count += 1
            if count % 2 == 0:
                cur = group_prev.next
                for _ in range(count - 1):
                    nxt = cur.next
                    cur.next = nxt.next
                    nxt.next = group_prev.next
                    group_prev.next = nxt
                group_prev = cur
            else:
                group_prev = tail
            size += 1
        return dummy.next

